Connect the app to the primary endpoint on port `6379` using TLS (`rediss://`). Grant the app permission to read the Secrets Manager secret for the auth token. **Protect your Terraform state** with encrypted, tightly restricted remote storage: the generated token is stored in state even though Terraform marks it sensitive.

**Pick: Amazon ElastiCache for Valkey** — Redis-compatible, managed, cheaper than Redis OSS, and great for sessions + caching. Use a Multi-AZ replication group with automatic failover, encryption in transit/at rest, and an AUTH token stored in Secrets Manager.

If you want zero capacity management, look at **ElastiCache Serverless** instead. The Terraform below is the provisioned Multi-AZ version, which is usually the right default for a web app launch.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.60.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.6.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region"
}

variable "name" {
  type        = string
  description = "Name prefix for resources"
}

variable "vpc_id" {
  type        = string
  description = "VPC ID"
}

variable "private_subnet_ids" {
  type        = list(string)
  description = "Private subnet IDs for ElastiCache"
}

variable "app_security_group_id" {
  type        = string
  description = "Security group ID of the web app that needs Redis/Valkey access"
}

variable "node_type" {
  type        = string
  default     = "cache.m7g.large"
  description = "ElastiCache node type. Scale up for more memory/CPU."
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Tags to apply"
}

# --------------------------------------------------------------------
# AUTH token stored in Secrets Manager
# --------------------------------------------------------------------

resource "random_password" "redis_auth" {
  length  = 64
  special = false
}

resource "aws_secretsmanager_secret" "redis_auth" {
  name = "${var.name}/redis/auth"
  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "redis_auth" {
  secret_id     = aws_secretsmanager_secret.redis_auth.id
  secret_string = random_password.redis_auth.result
}

# --------------------------------------------------------------------
# Networking
# --------------------------------------------------------------------

resource "aws_elasticache_subnet_group" "this" {
  name       = "${var.name}-cache-subnets"
  subnet_ids = var.private_subnet_ids

  tags = var.tags
}

resource "aws_security_group" "redis" {
  name_prefix = "${var.name}-redis-"
  description = "ElastiCache Valkey access"
  vpc_id      = var.vpc_id

  ingress {
    description     = "Valkey from web app"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [var.app_security_group_id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = var.tags
}

# --------------------------------------------------------------------
# Parameter group
# volatile-lru: evict only keys with TTL, so cache keys expire but
# session keys without TTL are protected. Set TTLs on cache keys.
# --------------------------------------------------------------------

resource "aws_elasticache_parameter_group" "this" {
  name        = "${var.name}-cache-params"
  family      = "valkey7"
  description = "Valkey parameter group for sessions and cache"

  parameter {
    name  = "maxmemory-policy"
    value = "volatile-lru"
  }

  parameter {
    name  = "tcp-keepalive"
    value = "300"
  }

  tags = var.tags
}

# --------------------------------------------------------------------
# Logging
# --------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "redis_slow" {
  name              = "/aws/elasticache/${var.name}/slow-log"
  retention_in_days = 30
  tags              = var.tags
}

# --------------------------------------------------------------------
# ElastiCache for Valkey: 1 primary + 1 replica, Multi-AZ failover
# --------------------------------------------------------------------

resource "aws_elasticache_replication_group" "this" {
  replication_group_id = "${var.name}-cache"
  description          = "Managed Valkey for sessions and caching"

  engine               = "valkey"
  engine_version       = "7.2"
  node_type            = var.node_type
  num_cache_clusters   = 2
  parameter_group_name = aws_elasticache_parameter_group.this.name

  automatic_failover_enabled = true
  multi_az_enabled           = true

  at_rest_encryption_enabled = true
  transit_encryption_enabled = true
  transit_encryption_mode    = "required"
  auth_token                 = random_password.redis_auth.result
  auth_token_update_strategy = "ROTATE"

  subnet_group_name  = aws_elasticache_subnet_group.this.name
  security_group_ids = [aws_security_group.redis.id]

  snapshot_retention_limit = 7
  snapshot_window          = "03:00-04:00"
  maintenance_window       = "sun:05:00-sun:06:00"

  auto_minor_version_upgrade = true
  apply_immediately          = false

  log_delivery_configuration {
    destination      = aws_cloudwatch_log_group.redis_slow.name
    destination_type = "cloudwatch-logs"
    log_format       = "json"
    log_type         = "slow-log"
  }

  tags = var.tags
}

# --------------------------------------------------------------------
# Outputs
# --------------------------------------------------------------------

output "redis_primary_endpoint" {
  value       = aws_elasticache_replication_group.this.primary_endpoint_address
  description = "Primary endpoint for writes/reads"
}

output "redis_reader_endpoint" {
  value       = aws_elasticache_replication_group.this.reader_endpoint_address
  description = "Reader endpoint for read scaling"
}

output "redis_auth_secret_arn" {
  value       = aws_secretsmanager_secret.redis_auth.arn
  description = "Secrets Manager ARN containing the AUTH token"
}
```

**Notes for production:**

- Use private subnets only. Never expose ElastiCache publicly.
- Pull the AUTH token from Secrets Manager at runtime; don’t bake it into app config.
- If you mix sessions and cache in one cluster, set TTLs on cache keys and use `volatile-lru`. For strict isolation, run two clusters: one for sessions, one for cache.
- Monitor `Evictions`, `CurrConnections`, `EngineCPUUtilization`, `CacheHits`, `CacheMisses`, and `ReplicationLag`.
- If you outgrow one shard, either scale up `node_type` or move to cluster mode enabled.

I’d pick **Amazon ElastiCache for Valkey** — Redis-compatible, managed, Multi-AZ, and usually the right fit for sessions + cache. For a typical web app, start with a **cluster-mode-disabled replication group**: 1 primary + 1 replica, TLS, auth token, private subnets, and a security group locked down to your app.

If traffic is very spiky and you want zero capacity planning, consider **ElastiCache Serverless** instead. The Terraform below is the provisioned Valkey setup.

```hcl
