  secret_string = random_password.redis_auth_token.result
}

resource "aws_elasticache_subnet_group" "main" {
  name       = lower("${var.environment}-redis-subnets")
  subnet_ids = var.private_subnet_ids
}

resource "aws_security_group" "redis" {
  name_prefix = lower("${var.environment}-redis-")
  description = "Allow app access to ElastiCache Valkey"
  vpc_id      = var.vpc_id

  ingress {
    description     = "Valkey from web app"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [var.app_security_group_id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "${var.environment}-redis"
    Environment = var.environment
  }
}

resource "aws_elasticache_parameter_group" "main" {
  name   = lower("${var.environment}-valkey7")
  family = "valkey7"

  parameter {
    name  = "maxmemory-policy"
    value = "volatile-lru" # evicts keys with TTL; set TTLs on cache/session keys
  }

  tags = {
    Environment = var.environment
  }
}

resource "aws_elasticache_replication_group" "main" {
  replication_group_id = lower("${var.environment}-app")
  description          = "Valkey for web app sessions and cache"

  engine               = "valkey"
  engine_version       = "7.2"
  node_type            = var.node_type
  port                 = 6379
  parameter_group_name = aws_elasticache_parameter_group.main.name

  num_cache_clusters         = 2
  automatic_failover_enabled = true
  multi_az_enabled           = true

