variable "node_type"         { type = string, default = "cache.r7g.large" }
variable "engine_version"    { type = string, default = "7.2" }
variable "num_cache_clusters" { type = number, default = 2 }          # 1 primary + 1 replica
variable "snapshot_retention_limit" { type = number, default = 3 }    # 0 = treat as pure cache
variable "maintenance_window" { type = string, default = "sun:04:30-sun:05:30" }
variable "tags"              { type = map(string), default = {} }

# ── Networking ───────────────────────────────────────────────
resource "aws_security_group" "this" {
  name        = "${var.name}-redis"
  description = "ElastiCache node access"
  vpc_id      = var.vpc_id
}

resource "aws_vpc_security_group_ingress_rule" "from_app" {
  for_each                     = toset(var.app_security_group_ids)
  security_group_id            = aws_security_group.this.id
  referenced_security_group_id = each.value
  ip_protocol                  = "tcp"
  from_port                    = 6379
  to_port                      = 6379
  description                  = "Valkey from app tier"
}

# Node-to-node replication traffic (self-reference)
resource "aws_vpc_security_group_ingress_rule" "self" {
  security_group_id            = aws_security_group.this.id
  referenced_security_group_id = aws_security_group.this.id
  ip_protocol                  = "tcp"
  from_port                    = 6379
  to_port                      = 6379
}

resource "aws_vpc_security_group_egress_rule" "self" {
  security_group_id            = aws_security_group.this.id
  referenced_security_group_id = aws_security_group.this.id
  ip_protocol                  = "tcp"
  from_port                    = 6379
  to_port                      = 6379
}

resource "aws_elasticache_subnet_group" "this" {
  name       = "${var.name}-subnets"
  subnet_ids = var.subnet_ids
}

# ── Auth token (in addition to network + TLS) ────────────────
