  comparison_operator = "GreaterThanThreshold"
  threshold           = 90
  evaluation_periods  = 3
  period              = 300
  dimensions          = { CacheClusterId = each.key }
  alarm_actions       = []
}

resource "aws_cloudwatch_metric_alarm" "evictions" {
  for_each            = local.cluster_ids
  alarm_name          = "${each.key}-evictions"
