  security_group_id = aws_security_group.this.id
  description       = "Intra-VPC only"
  ip_protocol       = "-1"
  cidr_ipv4         = data.aws_vpc.this.cidr_block
}

resource "aws_elasticache_subnet_group" "this" {
  name       = "${var.name}-cache-subnets"
  subnet_ids = var.private_subnet_ids
}

# --- Per-store parameter groups (maxmemory-policy is the whole point) -----

resource "aws_elasticache_parameter_group" "this" {
  for_each = local.stores

  name        = "${var.name}-${each.key}-params"
  family      = local.parameter_group_family
  description = "${each.value.description} - ${each.value.maxmemory_policy}"

  parameter {
    name  = "maxmemory-policy"
    value = each.value.maxmemory_policy
  }
}

# --- One AUTH token per cluster (compromising one must not open the other) -

resource "random_password" "auth_token" {
  for_each = local.stores

  length  = 32
  special = false # keeps connection URIs free of escaping surprises
}

# --- Replication groups ----------------------------------------------------

resource "aws_elasticache_replication_group" "this" {
  for_each = local.stores

  replication_group_id = "${var.name}-${each.key}" # <= 40 chars, [a-z0-9-]
  description          = each.value.description

  engine               = var.engine
  engine_version       = var.engine_version
  node_type            = each.value.node_type
  parameter_group_name = aws_elasticache_parameter_group.this[each.key].name
  port                 = local.port

  # Cluster mode disabled: one endpoint, primary + replicas.
  num_cache_clusters         = var.num_cache_clusters
  automatic_failover_enabled = var.num_cache_clusters > 1
  multi_az_enabled           = var.num_cache_clusters > 1

  subnet_group_name  = aws_elasticache_subnet_group.this.name
  security_group_ids = [aws_security_group.this.id]

  at_rest_encryption_enabled = true
  transit_encryption_enabled = true # required for auth_token; TLS on the wire
  auth_token                 = random_password.auth_token[each.key].result

  snapshot_retention_limit = each.value.snapshot_retention
  snapshot_window          = var.snapshot_window
  maintenance_window       = var.maintenance_window

  deletion_protection_enabled = var.deletion_protection
  apply_immediately           = false # edits land in the maintenance window

  tags = { Name = "${var.name}-${each.key}" }
}

# --- Publish connection info where the app can read it (not in the image) --

resource "aws_ssm_parameter" "primary_endpoint" {
  for_each = aws_elasticache_replication_group.this

  name = "/${var.name}/elasticache/${each.key}/primary_endpoint_address"
  type = "String"
  value = each.value.primary_endpoint_address
}

resource "aws_ssm_parameter" "reader_endpoint" {
  for_each = aws_elasticache_replication_group.this

  name = "/${var.name}/elasticache/${each.key}/reader_endpoint_address"
  type = "String"
  value = each.value.reader_endpoint_address
}

resource "aws_ssm_parameter" "auth_token" {
  for_each = local.stores

  name  = "/${var.name}/elasticache/${each.key}/auth_token"
  type  = "SecureString"
  value = random_password.auth_token[each.key].result
}
```

### `outputs.tf`

```hcl
output "endpoints" {
  description = "Primary/reader hosts per store. Tokens live in SSM, not here."
  value = {
    for k, rg in aws_elasticache_replication_group.this : k => {
      host        = rg.primary_endpoint_address
      reader_host = rg.reader_endpoint_address
      port        = local.port
      auth_token  = aws_ssm_parameter.auth_token[k].name # SSM path
    }
  }
}

output "security_group_id" {
  value = aws_security_group.this.id
}

output "replication_group_ids" {
  value = { for k, rg in aws_elasticache_replication_group.this : k => rg.id }
}
```

*(If you flip to cluster mode enabled later, read `configuration_endpoint_address` instead of `primary_endpoint_address` — the latter is empty when sharded.)*

