## Terraform

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ------------------------------------------------------------------ inputs

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "name" {
  type    = string
  default = "webapp"
}

variable "vpc_id" {
  type = string
}

variable "private_subnet_ids" {
  type        = list(string)
  description = "At least two AZs. Must be private subnets."
}

variable "app_security_group_id" {
  type        = string
  description = "SG of the web/app tier that dials out to 6379."
}

variable "node_type" {
  type    = string
  default = "cache.t4g.small" # Graviton; ~$15/mo per node
}

variable "engine_version" {
  type    = string
  default = "7.1"
}

# ---------------------------------------------------- network / access

resource "aws_security_group" "redis" {
  name        = "${var.name}-redis"
  description = "ElastiCache Redis: sessions + app cache"
  vpc_id      = var.vpc_id

  # Ingress only from the app tier. Redis makes no outbound calls,
  # so we deliberately define no egress rules.
  ingress {
    description     = "App tier on 6379"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [var.app_security_group_id]
  }

  tags = {
    Name = "${var.name}-redis"
  }
}

resource "aws_elasticache_subnet_group" "redis" {
  name       = "${var.name}-redis"
  subnet_ids = var.private_subnet_ids

  tags = {
    Name = "${var.name}-redis"
  }
}

# ------------------------------------------------- engine configuration

# volatile-lru = only evict keys that have a TTL set, least-recently-used
# first. Protects active sessions while shedding cold cache entries.
# Requires: every key you write must carry an expiry (EX/PX).
resource "aws_elasticache_parameter_group" "redis" {
  name   = "${var.name}-redis"
  family = "redis7"

  parameter {
    name  = "maxmemory-policy"
    value = "volatile-lru"
  }

  # Drop idle client connections after 5 minutes so leaked sockets
  # don't pin memory.
  parameter {
    name  = "timeout"
    value = "300"
  }

  parameter {
    name  = "tcp-keepalive"
    value = "60"
  }
}

# -------------------------------------------------------- auth material

# Auth token: 16-128 ASCII chars. `special = false` avoids URL-encoding
# pain when you paste it into a `rediss://` connection string.
resource "random_password" "auth_token" {
  length  = 64
  special = false
}

# ------------------------------------------------------------ the store

resource "aws_elasticache_replication_group" "redis" {
  replication_group_id = "${var.name}-redis"
  description          = "User sessions and application cache"

  engine         = "redis"
  engine_version = var.engine_version
  node_type      = var.node_type
  port           = 6379

  parameter_group_name = aws_elasticache_parameter_group.redis.name
  subnet_group_name    = aws_elasticache_subnet_group.redis.name
  security_group_ids   = [aws_security_group.redis.id]

  # Cluster-mode DISABLED: one primary (all writes) + one replica.
  # Two nodes is enough for automatic failover; sharding adds cost and
  # client complexity you don't need at launch.
  num_cache_clusters         = 2
  multi_az_enabled           = false
  automatic_failover_enabled = true

  # Session data is PII-adjacent -> encrypt both ways, require AUTH.
  at_rest_encryption_enabled = true
  transit_encryption_enabled = true
  auth_token                 = random_password.auth_token.result
  # Omit `kms_key_id` to use the AWS-managed key; supply a CMK ARN
  # if you need key-level rotation/deletion control.

  # 7 days of snapshots so an accidental FLUSHALL isn't unrecoverable.
  snapshot_retention_limit = 7
  snapshot_window          = "04:00-05:00" # UTC
  maintenance_window       = "sun:05:00-sun:06:00" # UTC

  auto_minor_version_upgrade = true
  apply_immediately          = false # stage changes into the window

  tags = {
    Name = "${var.name}-redis"
  }
}

# --------------------------------------------------------------- outputs

output "primary_endpoint" {
  description = "Writes: sessions, cache set/del. Format: hostname:port"
  value       = aws_elasticache_replication_group.redis.primary_endpoint_address
}

output "reader_endpoint" {
  description = "Reads: use for pure cache GETs to offload the primary."
  value       = aws_elasticache_replication_group.redis.reader_endpoint_address
}

output "auth_token" {
  description = "Store in Secrets Manager / SSM SecureString, not in git."
  value       = random_password.auth_token.result
  sensitive   = true
}

output "connection_url" {
  value = "rediss://:${random_password.auth_token.result}@${aws_elasticache_replication_group.redis.primary_endpoint_address}:6379/0"
  sensitive = true
}
```

